/* lyrel agent-hook omp bridge — generated by lyrel, do not edit. */
import type { ExtensionAPI, ExtensionContext } from "@oh-my-pi/pi-coding-agent";
import { getActiveProfile } from "@oh-my-pi/pi-utils";
import { spawnSync } from "node:child_process";

// The pane's daemon owns the executable on this Host. An installed extension
// can outlive the installation path that generated it (upgrade/portable move).
const EXE = process.env.LYREL_AGENT_HOOK_EXE || __EXE__;
// Injected from session_operations::OMP_SCOPE_ENV, not a second policy list.
const SCOPE_ENV = __SCOPE_ENV__;

export default function (omp: ExtensionAPI) {
  if (!process.env.LYREL) return;
  let warned = false;
  let lastAssistant: {stopReason: string; errorMessage?: string} | undefined;
  let titleWatch: Timer | undefined;
  let lastTitle: {sessionId: string; title: string} | undefined;
  function syncTitle(ctx: ExtensionContext) {
    if (ctx.agent.kind !== "main") return;
    const sessionId = ctx.sessionManager.getSessionId();
    const title = ctx.sessionManager.getSessionName()?.replace(/[\u0000-\u001f\u007f-\u009f]/g, "").trim();
    if (!title) { lastTitle = undefined; return; }
    if (lastTitle?.sessionId === sessionId && lastTitle.title === title) return;
    lastTitle = {sessionId, title};
    ctx.ui.setTitle(title);
    // OMP's Windows title API uses SetConsoleTitleW. Mirror this metadata once
    // into the pane stream too, rather than relying on a conhost title event.
    if (process.platform === "win32" && process.stdout.isTTY) process.stdout.write(`\x1b]2;${title}\x07`);
  }
  function emit(event: string, ctx: ExtensionContext, extra: Record<string, unknown> = {}) {
    // Child extension factories bind independent contexts; module globals do not identify the pane.
    if (ctx.agent.kind !== "main") return;
    const session_id = ctx.sessionManager.getSessionId();
    const environment = Object.fromEntries(SCOPE_ENV.filter(key => process.env[key] !== undefined).map(key => [key, process.env[key]]));
    const body = {
      session_id, cwd: ctx.sessionManager.getCwd(),
      session_scope: {
        profile: getActiveProfile() ?? "default", environment,
        session_file: ctx.sessionManager.getSessionFile(),
        session_dir: ctx.sessionManager.getSessionDir(),
      },
      ...extra,
    };
    const result = spawnSync(EXE, ["agent-hook", "omp", event], {
      input: JSON.stringify(body), stdio: ["pipe", "ignore", "pipe"],
      windowsHide: true, timeout: 5000,
    });
    if (result.error || result.status !== 0 || !session_id) {
      if (!warned) {
        warned = true;
        const reason = !session_id ? "missing session identity" : result.error?.message ?? (result.signal ? `signal ${result.signal}` : `exit ${result.status}`);
        ctx.ui.notify(`lyrel OMP status bridge unavailable (${reason}); status and session identity may be stale. Check the selected host integration and daemon.`, "warning");
      }
    }
  }
  function sameSession(sessionId: string, ctx: ExtensionContext) {
    return sessionId === ctx.sessionManager.getSessionId();
  }
  function started(ctx: ExtensionContext) {
    if (ctx.agent.kind !== "main") return;
    if (titleWatch !== undefined) ctx.clearTimer(titleWatch);
    syncTitle(ctx);
    // There is no public title-change extension event. A managed, deduplicated
    // watch covers /rename and automatic names without owning every OSC title.
    titleWatch = ctx.setInterval(() => syncTitle(ctx), 1000);
    lastAssistant = undefined;
    emit("session-start", ctx);
    const review = ctx.getPendingPlanReview();
    if (review && sameSession(review.sessionId, ctx)) {
      emit("question-asked", ctx, {request: {id: review.reviewId, kind: "plan-review"}, message: review.title});
    }
  }
  omp.on("session_start", (_event, ctx) => started(ctx));
  omp.on("session_switch", (_event, ctx) => started(ctx));
  omp.on("session_branch", (_event, ctx) => started(ctx));
  omp.on("session_tree", (_event, ctx) => started(ctx));
  omp.on("agent_start", (_event, ctx) => { lastAssistant = undefined; emit("prompt-submit", ctx); });
  omp.on("turn_start", (_event, ctx) => emit("prompt-submit", ctx));
  omp.on("auto_retry_start", (_event, ctx) => emit("prompt-submit", ctx));
  omp.on("auto_compaction_start", (_event, ctx) => emit("prompt-submit", ctx));
  omp.on("message_end", (event, ctx) => {
    if (ctx.agent.kind === "main" && event.message.role === "assistant") {
      lastAssistant = {stopReason: event.message.stopReason, errorMessage: event.message.errorMessage};
    }
  });
  omp.on("agent_end", (event, ctx) => {
    emit("agent-end", ctx, {
      willContinue: event.willContinue, awaitingAsyncWork: event.awaitingAsyncWork,
      // Never send transcript content, tool output, or provider credentials to the bridge.
      last_assistant: lastAssistant,
    });
  });
  omp.on("tool_approval_requested", (event, ctx) => {
    if (sameSession(event.sessionId, ctx)) emit("permission-request", ctx, {
      request: {id: event.toolCallId, kind: "permission"}, message: event.reason,
    });
  });
  omp.on("tool_approval_resolved", (event, ctx) => {
    if (sameSession(event.sessionId, ctx)) emit("tool-complete", ctx, {
      request: {id: event.toolCallId, kind: "permission", resolved: true},
      message: event.approved ? undefined : event.reason ?? "permission denied",
    });
  });
  omp.on("plan_review_requested", (event, ctx) => {
    if (sameSession(event.sessionId, ctx)) emit("question-asked", ctx, {
      request: {id: event.reviewId, kind: "plan-review"}, message: event.title,
    });
  });
  omp.on("plan_review_resolved", (event, ctx) => {
    if (sameSession(event.sessionId, ctx)) emit("tool-complete", ctx, {
      request: {id: event.reviewId, kind: "plan-review", resolved: true},
    });
  });
  omp.on("tool_execution_start", (event, ctx) => {
    if (event.toolName === "ask") emit("question-asked", ctx, {request: {id: event.toolCallId, kind: "question"}});
  });
  omp.on("tool_execution_end", (event, ctx) => emit("tool-complete", ctx,
    event.toolName === "ask" ? {request: {id: event.toolCallId, kind: "question", resolved: true}} : {}));
  // A process exit is not a successful turn completion.
  omp.on("session_shutdown", (_event, ctx) => emit("session-end", ctx));
}
